tool_input.command:
cat > test-scratch/test-sdk.js << 'EOF'
import { Eval } from 'frai-core';

const evaluations = Eval.runEvaluations({
  outputs: ['Hello', 'World', 'Test'],
  references: ['hello', 'world', 'test']
});

const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});

console.log('passed:', report.passed);
console.log('thresholds:', report.thresholds);
EOF
